#!/usr/bin/env python3
"""Writes __CRT_UUID_DECL lines for every interface in Microsoft's WebView2.h,
so MinGW's __uuidof() works with the SDK's own header (MSVC doesn't need them).

    python3 tools/webview2-uuids.py libs/third_party/webview2-sdk/WebView2.h \
        > libs/third_party/webview2-sdk/WebView2MinGW.h
"""
import re
import sys

src = open(sys.argv[1], encoding="utf-8").read()
pat = re.compile(r"const IID IID_(\w+) = \{(0x[0-9A-Fa-f]+),(0x[0-9A-Fa-f]+),(0x[0-9A-Fa-f]+),\{([^}]*)\}\};")
out = [
    "// Generated by tools/webview2-uuids.py from WebView2.h. Do not edit.",
    "// Include instead of WebView2.h: it adds the __uuidof() declarations MinGW needs.",
    "#pragma once",
    "#if defined(__GNUC__)",
    "#pragma GCC diagnostic push",
    "#pragma GCC diagnostic ignored \"-Wunknown-pragmas\"   // the MIDL header's #pragma warning lines",
    "#endif",
    "#include \"WebView2.h\"",
    "#if defined(__GNUC__)",
    "#pragma GCC diagnostic pop",
    "#endif",
    "#if defined(__MINGW32__) && defined(__cplusplus)",
]
seen = set()
for m in pat.finditer(src):
    name = m.group(1)
    if name in seen:
        continue
    seen.add(name)
    bytes_ = ",".join(b.strip() for b in m.group(5).split(","))
    out.append(f"__CRT_UUID_DECL({name}, {m.group(2)},{m.group(3)},{m.group(4)}, {bytes_})")
out.append("#endif")
print("\n".join(out))
sys.stderr.write(f"{len(seen)} interfaces\n")
